import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson, putJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { SheetPage } from '../../slots/defs/sheetPage';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { claimsKey, type Claim } from '../claims/claims';
import { tagsKey } from '../tags/tags';
import { usePeopleDue } from '../header/totals';
import { peopleKey, shownName, SORT_KEYS, sortPeople, useEditingPerson, usePeople, useShowRetired, useSortBy, type Person } from './people';
import { useGradeCodes } from '../grades/grades';
import { useShownColumns } from '../columns/columns';
import { useCrews, type Crew } from '../crews/crews';
import { useActingRole } from '../roles/roles';

/** The ids of the people a restricted user may see on the list: the person with the user's name (case and outer
 *  spaces ignored) and everyone in the crews that person leads or belongs to. */
function visibleTo(user: string, people: Person[], crews: Crew[]): Set<number> {
  const me = people.find((p) => p.name.trim().toLowerCase() === user.trim().toLowerCase());
  const ids = new Set<number>();
  if (!me) return ids;
  ids.add(me.id);
  for (const c of crews) {
    if (c.leadId !== me.id && !c.members.some((m) => m.personId === me.id)) continue;
    if (c.leadId !== null) ids.add(c.leadId);
    c.members.forEach((m) => ids.add(m.personId));
  }
  return ids;
}

/** The form's values. `gradeFrom` (yyyy-MM-dd) is the date the grade is given from; blank, the sheet's today. A
 *  person's first grade applies from the beginning of time. `terms` are the person's own terms in days; blank, none. `termsFrom` (yyyy-MM-dd) is the date they are given from;
 *  blank, the beginning of time. `contact` is the person's contact, kept by the server
 *  without surrounding spaces and lower-cased; blank, none. `tags` are the person's tags, comma separated, kept by the server
 *  each trimmed and lower-cased, repeats dropped; blank, none. */
type Values = { name: string; grade: string; gradeFrom: string; terms: string; termsFrom: string; contact: string; tags: string };
const EMPTY: Values = { name: '', grade: 'A', gradeFrom: '', terms: '', termsFrom: '', contact: '', tags: '' };

/** The form's values for a person as stored. */
const valuesOf = (p: Person): Values => ({
  name: p.name,
  grade: p.grade,
  gradeFrom: '',
  terms: p.terms === null ? '' : String(p.terms),
  termsFrom: '',
  contact: p.contact ?? '',
  tags: (p.tags ?? []).join(', '),
});

type Quick = { name: string; amount: string };
const NO_QUICK: Quick = { name: '', amount: '' };

/** The quick-add bar: a DRAFT claim of the amount, dated the sheet's today with an empty note, for the person with the
 *  name (case and outer spaces ignored); a name not on the sheet adds the person, grade A, first. The server does it as
 *  one change, so a refused claim adds no person. */
function QuickAdd({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const [values, setValues] = useState<Quick>(NO_QUICK);
  const submit = useSubmitOnce();
  const add = useMutation({
    mutationFn: (v: Quick) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/quick-add`, { ...v, by: user }),
    onSuccess: () => {
      setValues(NO_QUICK);
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
    },
    onSettled: submit.end,
  });
  const change = (v: Partial<Quick>) => {
    setValues((was) => ({ ...was, ...v }));
    add.reset();
  };

  return (
    <form
      data-testid="quick-add"
      onSubmit={(e) => {
        e.preventDefault();
        if (!submit.begin()) return;
        add.reset();
        add.mutate(values);
      }}
    >
      Quick add{' '}
      <input data-testid="quick-name" placeholder="Name" value={values.name} onChange={(e) => change({ name: e.target.value })} />{' '}
      <input
        data-testid="quick-amount"
        placeholder="Amount"
        inputMode="decimal"
        value={values.amount}
        onChange={(e) => change({ amount: e.target.value })}
      />{' '}
      <button type="submit" data-testid="quick-submit" disabled={add.isPending}>
        Add draft claim
      </button>
      {add.isError && (
        <span data-testid="quick-error">
          {' '}
          {values.name.trim() === ''
            ? 'A name is required.'
            : "The amount must be 0.00 or more, with up to two decimals, its due-by not inside a closed period, and not after the person's retirement date."}
        </span>
      )}
    </form>
  );
}

/** The sheet's people: a form that adds a person or saves the one being edited, and the list. The editor
 *  remembers the version of the person it loaded; a save refused because someone else saved the person since
 *  (412) shows the error and puts the current values, and their version, in the form; an edit refused otherwise shows the
 *  error and closes the editor. */
function People({ sheetId, user }: { sheetId: string; user: string }) {
  const gradeCodes = useGradeCodes(sheetId);
  const shown = useShownColumns(user);
  const people = usePeople(sheetId);
  const [showRetired, setShowRetired] = useShowRetired();
  const [sortBy, setSortBy] = useSortBy();
  const due = usePeopleDue(sheetId);
  const role = useActingRole(sheetId, user);
  const crews = useCrews(sheetId);
  // until the user's role is known, no row shows: a restricted user never glimpses another's row
  const restricted = role.data ? role.data.role === 'restricted' : user.trim() !== '' && !role.isError;
  const visible = restricted ? visibleTo(user, people.data ?? [], crews.data ?? []) : null;
  const queryClient = useQueryClient();
  const [editingId, setEditingId] = useEditingPerson();
  const editing = people.data?.find((p) => String(p.id) === editingId);
  const [values, setValues] = useState<Values>(EMPTY);
  const [version, setVersion] = useState<number | undefined>(undefined);
  const submit = useSubmitOnce();

  const save = useMutation({
    mutationFn: ({ id, ...v }: Values & { id?: number; version?: number }) => {
      const base = `/api/sheets/${encodeURIComponent(sheetId)}/people`;
      const body = { ...v, by: user };
      return id === undefined ? postJson<Person>(base, body) : putJson<Person>(`${base}/${id}`, body);
    },
    onSuccess: () => {
      setValues(EMPTY);
      setEditingId(undefined);
      setVersion(undefined);
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      void queryClient.invalidateQueries({ queryKey: tagsKey(sheetId) });
    },
    onError: async (error, { id }) => {
      if (id === undefined) return;
      if (!(error instanceof HttpError) || error.status !== 412) {
        // a refused edit closes the editor, its error still showing: the form is back to adding
        setValues(EMPTY);
        setVersion(undefined);
        setEditingId(undefined);
        return;
      }
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      const now = queryClient.getQueryData<Person[]>(peopleKey(sheetId))?.find((p) => p.id === id);
      if (now) {
        setValues(valuesOf(now));
        setVersion(now.version);
      }
    },
    onSettled: submit.end,
  });

  const change = (v: Partial<Values>) => {
    setValues((was) => ({ ...was, ...v }));
    save.reset();
  };
  const openEditor = (p: Person) => {
    save.reset();
    setValues(valuesOf(p));
    setVersion(p.version);
    setEditingId(String(p.id));
  };
  const cancel = () => {
    save.reset();
    setValues(EMPTY);
    setVersion(undefined);
    setEditingId(undefined);
  };

  return (
    <section data-testid="people">
      <h3>People</h3>
      <form
        data-testid="person-form"
        onSubmit={(e) => {
          e.preventDefault();
          if (!submit.begin()) return;
          save.reset();
          save.mutate(editing ? { ...values, id: editing.id, version } : values);
        }}
      >
        <label>
          Name{' '}
          <input data-testid="person-form-name" value={values.name} onChange={(e) => change({ name: e.target.value })} />
        </label>{' '}
        <label>
          Grade{' '}
          <select data-testid="person-form-grade" value={values.grade} onChange={(e) => change({ grade: e.target.value })}>
            {gradeCodes.map((g) => (
              <option key={g} value={g}>
                {g}
              </option>
            ))}
          </select>
        </label>{' '}
        <label>
          From{' '}
          <input
            data-testid="person-form-grade-from"
            placeholder="yyyy-mm-dd"
            value={values.gradeFrom}
            onChange={(e) => change({ gradeFrom: e.target.value })}
          />
        </label>{' '}
        <label>
          Terms{' '}
          <input
            data-testid="person-form-terms"
            placeholder="days"
            inputMode="numeric"
            value={values.terms}
            onChange={(e) => change({ terms: e.target.value })}
          />
        </label>{' '}
        <label>
          From{' '}
          <input
            data-testid="person-form-terms-from"
            placeholder="yyyy-mm-dd"
            value={values.termsFrom}
            onChange={(e) => change({ termsFrom: e.target.value })}
          />
        </label>{' '}
        <label>
          Contact{' '}
          <input data-testid="person-form-contact" value={values.contact} onChange={(e) => change({ contact: e.target.value })} />
        </label>{' '}
        <label>
          Tags{' '}
          <input
            data-testid="person-form-tags"
            placeholder="comma separated"
            value={values.tags}
            onChange={(e) => change({ tags: e.target.value })}
          />
        </label>{' '}
        <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
          {editing ? 'Save' : 'Add person'}
        </button>
        {editing && (
          <button type="button" data-testid="person-form-cancel" onClick={cancel}>
            Cancel
          </button>
        )}
        {save.isError && (
          <span data-testid="person-form-error">
            {(save.variables?.name ?? '').trim() === ''
              ? 'A name is required.'
              : save.error instanceof HttpError && save.error.status === 409
                ? 'That name or contact is already in use on this sheet.'
                : save.error instanceof HttpError && save.error.status === 412
                  ? 'Someone else saved this person since you opened it; the form now shows their values.'
                  : 'Could not save this person.'}
          </span>
        )}
      </form>
      <QuickAdd sheetId={sheetId} user={user} />
      <label>
        <input
          type="checkbox"
          data-testid="show-retired"
          checked={showRetired}
          onChange={(e) => setShowRetired(e.target.checked || undefined)}
        />{' '}
        Show retired
      </label>{' '}
      <label>
        Sort by{' '}
        <select data-testid="sort-by" value={sortBy || 'added'} onChange={(e) => setSortBy(e.target.value === 'added' ? undefined : e.target.value)}>
          {SORT_KEYS.map((k) => (
            <option key={k} value={k}>
              {k}
            </option>
          ))}
        </select>
      </label>
      {people.isError && <p data-testid="people-load-error">Could not load people.</p>}
      <table data-testid="people-table">
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            {shown('terms') && <th>Terms</th>}
            {shown('contact') && <th>Contact</th>}
            <th>Tags</th>
            <PeopleHead.Slot sheetId={sheetId} user={user} />
            <th />
          </tr>
        </thead>
        <tbody>
          {sortPeople(people.data?.filter((p) => (showRetired || p.retiredFrom === null) && (visible === null || visible.has(p.id))) ?? [], sortBy, due).map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{shownName(p)}</td>
              <td data-testid="person-grade">{p.grade}</td>
              {shown('terms') && <td data-testid="person-terms">{p.terms ?? ''}</td>}
              {shown('contact') && <td data-testid="person-contact">{p.contact ?? ''}</td>}
              <td data-testid="person-tags">{(p.tags ?? []).join(', ')}</td>
              <PersonRow.Slot sheetId={sheetId} user={user} person={p} />
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => openEditor(p)}>
                  Edit
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPage.fill({ order: 10, Component: People });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { nowKey, useReadNow } from '../../query/readNow';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';

export const GRADES = ['A', 'B', 'C'] as const;

/** A grade a person has from a date (yyyy-MM-dd) until their next one's; a null `from` applies from the beginning of
 *  time (the first grade the person was given). */
export type PersonGrade = { grade: string; from: string | null };

/** A person on the sheet. `name` is unique on the sheet (case ignored), kept without outer spaces; `grades` are the
 *  grades recorded, by from-date, and `grade` (A, B or C) the one in force on the sheet's today.
 *  `version` goes up by one on each stored edit; an edit sends the version it was made from. `retiredFrom` (yyyy-MM-dd)
 *  is the date the person is retired from, null when not retired: a person with one counts as retired at once. `holds` are
 *  the person's holds, by from-date: a claim of theirs dated within one still counts in every total; a hold
 *  only takes the person's cut in the pools. `held` is whether they have any hold. `terms` are the person's own terms in days (ahead of
 *  their grade's and the sheet's when a claim is added) in force on the sheet's today, null when they have none;
 *  `ownTerms` are their own terms as recorded, by from-date (null: from the beginning of time), a claim having those in
 *  force on its date. `contact` is the person's contact
 *  (unique on the sheet; without surrounding spaces, lower-cased), null when none. `aliases` are the person's aliases,
 *  sorted as names are compared: no alias equals (case ignored) any name or alias on the sheet, and the quick-add bar and
 *  the paste box find a person by one as by the name. `clashing` is whether their name or an alias is used as a name or
 *  alias on another sheet of the sheet's tree (people added before the rule): every edit of them is refused until it
 *  renames them clear. `origin` is the sheet they were last transferred from, null when never transferred here.
 *  `retirements` are their past retirements (each ended by unretiring them), in the order they ended.
 *  `tags` are the person's tags (each trimmed and in lower case, no repeats, sorted; empty when none): a claim of theirs
 *  counts for each in the tag totals. */
/** A person's own terms in days (null: none) from a date (yyyy-MM-dd; null: the beginning of time). */
export type PersonTerms = { days: number | null; from: string | null };

export type Person = {
  id: number;
  sheetId: string;
  name: string;
  grade: string;
  version: number;
  retiredFrom: string | null;
  held: boolean;
  grades: PersonGrade[];
  holds: PersonHold[];
  terms: number | null;
  ownTerms: PersonTerms[];
  contact: string | null;
  aliases: string[];
  clashing: boolean;
  origin: string | null;
  retirements: PersonRetirement[];
  tags: string[];
  flag: PersonFlag | null;
};

/** A steward's flag on a person: its reason, in force until its until-date (yyyy-MM-dd, included). While the sheet's
 *  today is on or before it only a steward may open a claim of the person; after it the flag shows nothing. */
export type PersonFlag = { reason: string; until: string };

/** The reason of the person's flag in force on the day (yyyy-MM-dd), or '' when none is. */
export const flagOn = (person: Pick<Person, 'flag'>, on: string) =>
  person.flag && on !== '' && on <= person.flag.until ? person.flag.reason : '';

/** A past retirement of a person (yyyy-MM-dd): from their retirement date to the sheet's today when they were
 *  unretired. No claim of theirs may be dated after the from and before the to. */
export type PersonRetirement = { from: string; to: string };

/** A hold on a person from a date until a date (yyyy-MM-dd, both included); a null `to` is open-ended. */
export type PersonHold = { from: string; to: string | null };

/** Whether a hold of the person covers the date (yyyy-MM-dd). */
export const heldOn = (person: Pick<Person, 'holds'>, on: string) =>
  (person.holds ?? []).some((h) => h.from <= on && (h.to === null || on <= h.to));

/** Whether the person's retirement date is reached on the day (yyyy-MM-dd): it is on or before it. From then on their
 *  open (OPEN or PENDING) claims not bound by a statement count in no live total. */
export const retiredOn = (person: Pick<Person, 'retiredFrom'>, on: string) =>
  person.retiredFrom !== null && on !== '' && person.retiredFrom <= on;

/** The person's grade in force on a date (yyyy-MM-dd): the one with the latest from-date on or before it. */
export function gradeOn(person: Pick<Person, 'grade' | 'grades'>, on: string): string {
  let found: PersonGrade | undefined;
  for (const g of person.grades ?? []) {
    if (g.from !== null && g.from > on) continue;
    if (found === undefined || found.from === null || (g.from !== null && g.from > found.from)) found = g;
  }
  return found?.grade ?? person.grade;
}

/** How the screen shows a person's name: `<name> (<grade in force on the sheet's today>)`. Exports, audit lines, the
 *  import and paste boxes and the selects of names keep the plain name. */
export const shownName = (person: Pick<Person, 'name' | 'grade'>) => `${person.name} (${person.grade})`;

export const peopleKey = (sheetId: string) => ['sheet', sheetId, 'people'];

/** The sheet's people, in list order (new people at the end; see the move buttons). */
export function usePeople(sheetId: string) {
  const now = useReadNow();
  return useQuery({
    queryKey: nowKey(peopleKey(sheetId), now),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheetId)}/people`, now),
  });
}

/** The id of the person whose editor is open (in the person form), or '' when the form adds. */
export const useEditingPerson = () => useSearchParam('person', asString);

/** Whether retired people are listed. Off when the screen is first opened; loading a sheet leaves it as it is. */
export const useShowRetired = () => useSearchParam('retired', asFlag);

/** What the people list is sorted by on this screen: list order (added), name (as names are compared: case ignored),
 *  grade, or due-total (n/a last). Equal keys keep list order. Only the screen's order changes: every action in list
 *  order, and the rollups, still go by list order. */
export const SORT_KEYS = ['added', 'name', 'grade', 'due-total'] as const;
export const useSortBy = () => useSearchParam('sort', asString);

/** The people in the order the sort key gives; `due` is each person's due-total (two decimals, or n/a) by id. */
export function sortPeople(people: Person[], key: string, due: Map<number, string>): Person[] {
  const nameKey = (p: Person) => p.name.toLowerCase();
  const dueKey = (p: Person) => {
    const d = due.get(p.id);
    return d === undefined || d === 'n/a' ? Infinity : Number(d);
  };
  const cmp: ((a: Person, b: Person) => number) | undefined =
    key === 'name'
      ? (a, b) => (nameKey(a) < nameKey(b) ? -1 : nameKey(a) > nameKey(b) ? 1 : 0)
      : key === 'grade'
        ? (a, b) => (a.grade < b.grade ? -1 : a.grade > b.grade ? 1 : 0)
        : key === 'due-total'
          ? (a, b) => (dueKey(a) === dueKey(b) ? 0 : dueKey(a) < dueKey(b) ? -1 : 1)
          : undefined;
  return cmp === undefined ? people : [...people].sort(cmp); // Array.sort is stable: equal keys keep list order
}
