import { SheetPage } from '../../slots/defs/sheetPage';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { live, useClaims } from '../claims/claims';
import { usePeople, type Person } from '../people/people';
import { sum, useRates } from '../rates/rates';
import { useFloor, useLate } from '../settings/settings';
import { aged } from './aging';

function AgingHead() {
  return (
    <>
      <th>Due 0–30</th>
      <th>Due 31–60</th>
      <th>Due 61+</th>
    </>
  );
}

/** A person's due on their open claims that count, split by the claim's age (see aged). */
function PersonAging({ sheetId, person }: { sheetId: string; person: Person }) {
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const mine = live(claims.data?.filter((c) => c.personId === person.id) ?? [], [person], late.today);
  const a = aged(mine, rates.data, person, late, floor);
  return (
    <>
      <td data-testid="person-aged-0-30">{a.d30}</td>
      <td data-testid="person-aged-31-60">{a.d60}</td>
      <td data-testid="person-aged-61">{a.d61}</td>
    </>
  );
}

/** The sheet's due by age: everyone's age buckets added up, skipping n/a, with no trimming. */
function SheetAging({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const all = (people.data ?? []).map((p) =>
    aged(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p], late.today), rates.data, p, late, floor),
  );
  return (
    <p>
      Due 0–30 <span data-testid="rollup-aged-0-30">{sum(all.map((a) => a.d30))}</span>
      {' '}Due 31–60 <span data-testid="rollup-aged-31-60">{sum(all.map((a) => a.d60))}</span>
      {' '}Due 61+ <span data-testid="rollup-aged-61">{sum(all.map((a) => a.d61))}</span>
    </p>
  );
}

export const contributions = [
  SheetPage.fill({ order: 30.5, Component: SheetAging }),
  PeopleHead.fill({ order: 21, Component: AgingHead }),
  PersonRow.fill({ order: 21, Component: PersonAging }),
];
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { live, useClaims } from '../claims/claims';
import { overdue } from '../overdue/overdue';
import { type Person } from '../people/people';
import { personSplit, useRates } from '../rates/rates';
import { useFloor, useLate, useScoreThresholds } from '../settings/settings';
import { band, score } from './score';

function ScoreHead() {
  return (
    <>
      <th>Score</th>
      <th>Band</th>
    </>
  );
}

/** A person's score (see score), and their band by it (see band), over their claims that count in the live totals; its
 *  settled figures leave out corrections. */
function PersonScore({ sheetId, person }: { sheetId: string; person: Person }) {
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const mine = live(claims.data?.filter((c) => c.personId === person.id) ?? [], [person], late.today);
  const settled = personSplit(mine.filter((c) => !c.corrects), rates.data, person, late, floor).settled;
  const count = overdue(mine, rates.data, person, late, floor).count;
  const thresholds = useScoreThresholds(sheetId);
  const shown = score(settled, count);
  return (
    <>
      <td data-testid="person-score">{shown}</td>
      <td data-testid="person-band">{band(shown, thresholds.mid, thresholds.high)}</td>
    </>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 26, Component: ScoreHead }),
  PersonRow.fill({ order: 26, Component: PersonScore }),
];

/** A status log line as shown: `<STATUS> by <user> on <date> due=<due>`. */
export const logLine = (l: ClaimLogLine) => `${l.status} by ${l.by} on ${l.date} due=${l.due}`;

export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'];

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  const now = useReadNow();
  return useQuery({
    queryKey: nowKey(claimsKey(sheetId), now),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`, now),
  });
}

/** An amount ("12.34") in whole cents, so sums are exact. */
const cents = (amount: string) => Math.round(Number(amount) * 100);

/** Whether a claim is open: OPEN, or PENDING (handled like an OPEN claim). */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

 *  `dueBy` (yyyy-MM-dd) is its due-by, fixed when it was added from the terms in force on that day (its person's own, else their grade's, else the sheet's), or as a steward last set it directly (then kept, whatever holiday is added later);
 *  `deferred` is whether it is deferred on the sheet's today (a claim that counts, deferred until a date after it and
 *  not bound by a statement: it counts in no total, is not overdue and cannot be settled; while bound the deferral
 *  waits for the binding to end) and `deferredUntil` (yyyy-MM-dd) the date it was last deferred until (shown
 *  even once that date has passed; null when never deferred); `proofs` is its proofs count (a claim whose due is above the sheet's proof threshold
 *  on its date cannot be settled nor approved while it is 0); `splitFrom` is the number of the claim it was split from
 *  (null for any other claim); `log` is its status log, oldest first; `lockedBy` is who has its editor open (it is locked for
 *  everyone else; null when no one does). */
export type Claim = {
  id: number;
  sheetId: string;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  roundsOn: string;
  dueBy: string;
  deferred: boolean;
  deferredUntil: string | null;
  /** Whether a steward waived its late charge: from then on it bears none, whatever its overdue state. */
  waived: boolean;
  /** The user a steward last assigned it to for review (null when never): kept once it leaves REVIEW. */
  reviewAssigned: string | null;
  /** Whether it is held (an OPEN or PENDING claim is held and released with Hold): a held claim still counts in every
   *  total, as one dated within a hold of its person does. */
  held: boolean;
  proofs: number;
  /** How many of its proofs are receipts (the kind when none is chosen) and photos. */
  proofsReceipt: number;
  proofsPhoto: number;
  splitFrom: string | null;
  log: ClaimLogLine[];
  lockedBy: string | null;
  /** Whether it was added while the period its date falls in was soft-closed. */

